## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/psychiatryLogic.ts`

```typescript
// ─── Psychiatry Clinical Compass™ Logic Engine ────────────────────────────────
// Guidelines: APA 2025–2026, VA/DoD 2023–2024, SAMHSA, NICE
// Conditions: Delirium, BPD, Depression/TRD, Schizophrenia, Eating Disorders,
//             Benzo Tapering, PTSD, Suicide Risk, Bipolar Disorder
// ─────────────────────────────────────────────────────────────────────────────

export type PsychCondition =
  | "delirium"
  | "bpd"
  | "depression"
  | "schizophrenia"
  | "eating_disorder"
  | "benzo_tapering"
  | "ptsd"
  | "suicide_risk"
  | "bipolar";

// ─── Delirium ────────────────────────────────────────────────────────────────
export interface DeliriumInput {
  condition: "delirium";
  deliriumSubtype: "hyperactive" | "hypoactive" | "mixed" | "";
  severeSafetyRisk: boolean;       // agitation posing immediate danger
  preventionContext: boolean;      // ICU prevention setting
  icuPatient: boolean;
  substanceWithdrawal: boolean;    // alcohol/benzo withdrawal delirium
  age: number;
  dementiaDiagnosis: boolean;
  antipsychoticPrior: boolean;
}

// ─── BPD ─────────────────────────────────────────────────────────────────────
export interface BPDInput {
  condition: "bpd";
  diagnosisConfirmed: boolean;
  currentCrisis: boolean;          // acute SI/SH episode
  priorDBT: boolean;
  priorMBT: boolean;               // mentalization-based therapy
  comorbidMDD: boolean;
  comorbidBipolar: boolean;
  polypharmacy: boolean;           // ≥3 psychiatric medications
  substanceUse: boolean;
}

// ─── Depression ──────────────────────────────────────────────────────────────
export interface DepressionInput {
  condition: "depression";
  severity: "mild" | "moderate" | "severe" | "";
  trd: boolean;                    // treatment-resistant depression (≥2 adequate trials)
  trialsFailed: number;            // number of adequate antidepressant trials
  esketamineCandidacy: boolean;    // SPRAVATO eligibility
  suicidalIdeation: boolean;
  psychoticFeatures: boolean;
  bipolarHistory: boolean;
  pregnancyOrPostpartum: boolean;
  currentMedication: string;       // current antidepressant
  augmentationTried: boolean;
  ecgAbnormal: boolean;            // QTc prolongation
  measurementBasedCare: boolean;
}

// ─── Schizophrenia ───────────────────────────────────────────────────────────
export interface SchizophreniaInput {
  condition: "schizophrenia";
  firstEpisode: boolean;
  treatmentResistant: boolean;     // failed ≥2 antipsychotics
  clozapineEligible: boolean;
  metabolicConcerns: boolean;      // obesity, diabetes, dyslipidemia
  laiCandidate: boolean;           // long-acting injectable candidate
  nonadherence: boolean;
  comorbidSubstanceUse: boolean;
  tardiveDyskinesia: boolean;
  acuteExacerbation: boolean;
  currentAntipsychotic: string;
}

// ─── Eating Disorders ─────────────────────────────────────────────────────────
export interface EatingDisorderInput {
  condition: "eating_disorder";
  edType: "AN" | "BN" | "BED" | "ARFID" | "";  // anorexia, bulimia, binge eating, ARFID
  age: number;
  pediatric: boolean;              // age < 18
  medicallyUnstable: boolean;      // vitals, labs, cardiac
  bmi: number;
  priorFBT: boolean;               // family-based therapy
  priorCBT: boolean;
  priorIOP: boolean;               // intensive outpatient
  substanceUse: boolean;
  comorbidMDD: boolean;
}

// ─── Benzo Tapering ──────────────────────────────────────────────────────────
export interface BenzoTaperingInput {
  condition: "benzo_tapering";
  benzoName: string;               // diazepam, alprazolam, clonazepam, lorazepam
  durationYears: number;
  dailyDoseMg: number;
  anxietyComorbid: boolean;
  seizureHistory: boolean;
  withdrawalHistory: boolean;
  substanceUseDisorder: boolean;
  patientMotivated: boolean;
  outpatientSafe: boolean;
}

// ─── PTSD ─────────────────────────────────────────────────────────────────────
export interface PTSDInput {
  condition: "ptsd";
  traumaType: "combat" | "sexual_assault" | "accident" | "childhood" | "other" | "";
  severity: "mild" | "moderate" | "severe" | "";
  comorbidMDD: boolean;
  comorbidSUD: boolean;
  suicidalIdeation: boolean;
  priorPE: boolean;                // prolonged exposure therapy
  priorCPT: boolean;               // cognitive processing therapy
  priorEMDR: boolean;
  currentMedication: string;
  militaryVeteran: boolean;
  dissociativeSubtype: boolean;
}

// ─── Suicide Risk ─────────────────────────────────────────────────────────────
export interface SuicideRiskInput {
  condition: "suicide_risk";
  currentSI: boolean;             // current suicidal ideation
  plan: boolean;
  means: boolean;                 // access to lethal means
  intent: boolean;
  priorAttempt: boolean;
  hopelessness: boolean;
  socialIsolation: boolean;
  substanceUse: boolean;
  recentLoss: boolean;
  protectiveFactors: boolean;     // family support, religious beliefs, etc.
  comorbidMDD: boolean;
  comorbidBPD: boolean;
  militaryVeteran: boolean;
}

// ─── Bipolar ──────────────────────────────────────────────────────────────────
export interface BipolarInput {
  condition: "bipolar";
  bipolarType: "I" | "II" | "cyclothymia" | "";
  currentPhase: "manic" | "hypomanic" | "depressed" | "mixed" | "euthymic" | "";
  severity: "mild" | "moderate" | "severe" | "";
  psychoticFeatures: boolean;
  rapidCycling: boolean;           // ≥4 episodes/year
  mixedFeatures: boolean;
  pregnancyOrPostpartum: boolean;
  currentMedication: string;
  lithiumTried: boolean;
  valproateTried: boolean;
  lamotrigineTried: boolean;
  substanceUse: boolean;
  suicidalIdeation: boolean;
}

export type PsychiatryInput =
  | DeliriumInput
  | BPDInput
  | DepressionInput
  | SchizophreniaInput
  | EatingDisorderInput
  | BenzoTaperingInput
  | PTSDInput
  | SuicideRiskInput
  | BipolarInput;

export interface PsychRecommendation {
  condition: PsychCondition;
  primaryRecommendation: {
    indication: string;
    firstLineIntervention: string[];
    pharmacotherapy: string;
    psychotherapy: string;
    levelOfCare: string;
    cor: string;      // class of recommendation
    loe: string;      // level of evidence
    guidelineSource: string;
    notes: string;
  };
  alternativeRecommendations: Array<{
    indication: string;
    intervention: string;
    notes: string;
  }>;
  urgentFlags: string[];
  safetyConsiderations: string[];
  monitoringParameters: string[];
  multidisciplinaryConsult: string[];
  references: Array<{ citation: string; year: number }>;
  guidelineYear: string;
  practiceChangingNote?: string;   // for paradigm-shifting 2025 updates
}

// ─────────────────────────────────────────────────────────────────────────────
// MAIN EVALUATION FUNCTION
// ─────────────────────────────────────────────────────────────────────────────

export function evaluatePsychiatry(input: PsychiatryInput): PsychRecommendation {
  switch (input.condition) {
    case "delirium":      return evaluateDelirium(input);
    case "bpd":           return evaluateBPD(input);
    case "depression":    return evaluateDepression(input);
    case "schizophrenia": return evaluateSchizophrenia(input);
    case "eating_disorder": return evaluateEatingDisorder(input);
    case "benzo_tapering": return evaluateBenzoTapering(input);
    case "ptsd":          return evaluatePTSD(input);
    case "suicide_risk":  return evaluateSuicideRisk(input);
    case "bipolar":       return evaluateBipolar(input);
    default:              return insufficientData("unknown");
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// DELIRIUM — APA 2025 (PRACTICE-CHANGING)
// ─────────────────────────────────────────────────────────────────────────────

function evaluateDelirium(input: DeliriumInput): PsychRecommendation {
  const urgent: string[] = [];
  const safety: string[] = [];
  const monitoring: string[] = [];
  const mdtConsult: string[] = ["Geriatrics or Palliative Care", "Nursing (reorientation protocols)", "Pharmacy (medication review)"];

  if (input.substanceWithdrawal) {
    urgent.push("Alcohol/benzo withdrawal delirium — benzodiazepines are FIRST-LINE; antipsychotics are contraindicated");
  }
  if (input.dementiaDiagnosis) {
    urgent.push("Dementia increases delirium risk — minimize anticholinergics and sedatives");
    safety.push("Avoid antipsychotics in dementia-related delirium (increased mortality risk — FDA black box warning)");
  }
  if (input.age >= 65) {
    safety.push("Older adults: higher risk of antipsychotic-related falls, QTc prolongation, and extrapyramidal symptoms");
  }

  monitoring.push("CAM or CAM-ICU score q8h", "Vital signs and oxygenation", "Medication reconciliation for deliriogenic agents", "Sleep-wake cycle monitoring");

  // APA 2025 PRACTICE-CHANGING: Avoid antipsychotics for prevention or routine treatment
  let pharmacotherapy = "";
  let firstLine: string[] = [];
  let notes = "";
  let practiceChangingNote = "";

  if (input.preventionContext) {
    firstLine = ["Non-pharmacologic prevention bundle (HELP protocol)", "Sleep hygiene optimization", "Early mobilization", "Sensory aids (glasses, hearing aids)", "Hydration and nutrition optimization", "Reorientation interventions"];
    pharmacotherapy = "AVOID antipsychotics for prevention (APA 2025 — no benefit, potential harm)";
    notes = "APA 2025 PRACTICE CHANGE: Antipsychotics are NOT recommended for delirium prevention. Non-pharmacologic multicomponent interventions (HELP protocol) remain the standard of care.";
    practiceChangingNote = "APA 2025 PARADIGM SHIFT: Antipsychotics should NOT be used for delirium prevention or routine treatment. This is a major departure from prior practice.";
  } else if (input.substanceWithdrawal) {
    firstLine = ["Benzodiazepines (CIWA-Ar protocol)", "Thiamine 100 mg IV before glucose", "Electrolyte replacement"];
    pharmacotherapy = "Lorazepam or diazepam per CIWA-Ar protocol. Antipsychotics CONTRAINDICATED.";
    notes = "Alcohol/benzo withdrawal delirium requires benzodiazepines. Antipsychotics lower seizure threshold and are contraindicated.";
  } else if (input.severeSafetyRisk && !input.substanceWithdrawal) {
    firstLine = ["Non-pharmacologic de-escalation (first)", "Environmental modification", "One-to-one sitter"];
    pharmacotherapy = "Antipsychotics (haloperidol 0.5–1 mg IV/IM or quetiapine 12.5–25 mg PO) ONLY if severe distress or immediate safety risk — use lowest effective dose for shortest duration. APA 2025: Reserve for severe agitation only.";
    notes = "APA 2025: Antipsychotics are reserved ONLY for severe distress or immediate safety risk. Not for routine delirium management. Use lowest dose, shortest duration.";
    practiceChangingNote = "APA 2025 PRACTICE CHANGE: Antipsychotics are no longer recommended for routine delirium treatment. Use only for severe agitation posing immediate safety risk.";
  } else {
    firstLine = ["Non-pharmacologic multicomponent care (HELP protocol)", "Treat underlying cause", "Reorientation and cognitive stimulation", "Sleep-wake cycle optimization", "Early mobilization", "Minimize deliriogenic medications"];
    pharmacotherapy = "AVOID antipsychotics for routine delirium treatment (APA 2025). Address underlying etiology.";
    notes = "APA 2025 PRACTICE CHANGE: Antipsychotics do not improve outcomes in delirium and may cause harm. Focus on identifying and treating the underlying cause.";
    practiceChangingNote = "APA 2025 PARADIGM SHIFT: First major delirium guideline update in >20 years. Antipsychotics should NOT be used for prevention or routine treatment of delirium.";
  }

  return {
    condition: "delirium",
    primaryRecommendation: {
      indication: `Delirium — ${input.deliriumSubtype || "unspecified subtype"}${input.preventionContext ? " (prevention context)" : ""}${input.substanceWithdrawal ? " (withdrawal)" : ""}`,
      firstLineIntervention: firstLine,
      pharmacotherapy,
      psychotherapy: "Not applicable — behavioral/environmental interventions are primary",
      levelOfCare: input.icuPatient ? "ICU/Critical Care" : input.severeSafetyRisk ? "Inpatient Medical Unit with 1:1 sitter" : "Medical unit with delirium bundle",
      cor: "Strong",
      loe: "A",
      guidelineSource: "APA Practice Guideline for Delirium 2025",
      notes,
    },
    alternativeRecommendations: [
      {
        indication: "Refractory agitation in ICU delirium (not withdrawal)",
        intervention: "Dexmedetomidine (alpha-2 agonist) — preferred over antipsychotics in mechanically ventilated patients (MENDS2 trial)",
        notes: "Dexmedetomidine reduces delirium duration vs lorazepam in ICU. Consult critical care.",
      },
      {
        indication: "Melatonin for sleep-wake cycle disruption",
        intervention: "Melatonin 0.5–5 mg at bedtime (low-risk adjunct)",
        notes: "May help with sleep-wake cycle normalization. Not proven to reduce delirium duration.",
      },
    ],
    urgentFlags: urgent,
    safetyConsiderations: [
      ...safety,
      "QTc prolongation risk with haloperidol and other antipsychotics",
      "Fall prevention — bed alarms, low bed position",
      "Aspiration precautions",
      "Avoid physical restraints if possible (worsen delirium)",
    ],
    monitoringParameters: monitoring,
    multidisciplinaryConsult: mdtConsult,
    references: [
      { citation: "American Psychiatric Association. Practice Guideline for the Treatment of Patients with Delirium. 2025 (First update in >20 years)", year: 2025 },
      { citation: "Inouye SK et al. NEJM 1999 (HELP protocol — Hospital Elder Life Program)", year: 1999 },
      { citation: "Girard TD et al. NEJM 2018 (MIND-USA trial — haloperidol vs ziprasidone vs placebo in ICU delirium)", year: 2018 },
      { citation: "Skrobik Y et al. Crit Care Med 2018 (MENDS2 — dexmedetomidine vs lorazepam)", year: 2018 },
    ],
    guidelineYear: "2025",
    practiceChangingNote,
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// BPD — APA 2025
// ─────────────────────────────────────────────────────────────────────────────

function evaluateBPD(input: BPDInput): PsychRecommendation {
  const urgent: string[] = [];
  const safety: string[] = [];

  if (input.currentCrisis) {
    urgent.push("Acute suicidal/self-harm crisis — safety assessment and crisis plan required immediately");
  }
  if (input.polypharmacy) {
    safety.push("Polypharmacy (≥3 psychiatric medications) — APA 2025 recommends medication reduction; no medication is FDA-approved for BPD");
  }

  let firstLine: string[] = [];
  let pharmacotherapy = "";
  let notes = "";
  const practiceChangingNote = "APA 2025 PRACTICE CHANGE: Psychotherapy is the primary treatment for BPD. Pharmacotherapy should be adjunctive only, targeting specific symptoms (not BPD itself). Avoid polypharmacy.";

  if (!input.priorDBT && !input.priorMBT) {
    firstLine = ["Dialectical Behavior Therapy (DBT) — first-line (strongest evidence)", "Mentalization-Based Therapy (MBT) — first-line alternative", "Transference-Focused Psychotherapy (TFP)", "Schema-Focused Therapy"];
    pharmacotherapy = "No medication is FDA-approved for BPD. Adjunctive pharmacotherapy only for specific comorbid symptoms (e.g., mood instability: low-dose mood stabilizer; impulsivity: low-dose antipsychotic). Avoid polypharmacy.";
    notes = "APA 2025: Psychotherapy-first approach. DBT has the strongest evidence base. Pharmacotherapy is adjunctive and symptom-targeted, not disorder-targeted.";
  } else if (input.priorDBT && !input.priorMBT) {
    firstLine = ["Continue/optimize DBT", "Consider MBT as alternative", "Transference-Focused Psychotherapy (TFP)", "Good Psychiatric Management (GPM)"];
    pharmacotherapy = "Review and minimize current medications. Target specific symptoms only.";
    notes = "Prior DBT — consider MBT or TFP as alternatives. Medication review recommended to reduce polypharmacy.";
  } else {
    firstLine = ["Optimize current evidence-based psychotherapy", "Consider step-up to intensive outpatient or partial hospitalization", "Peer support and skills groups"];
    pharmacotherapy = "Medication review and reduction if polypharmacy present. Consider consultation with BPD specialist.";
    notes = "Prior DBT and MBT — consider higher level of care or specialist consultation.";
  }

  if (input.comorbidMDD) {
    firstLine.push("Treat comorbid MDD with SSRI/SNRI (standard MDD guidelines apply)");
  }
  if (input.substanceUse) {
    firstLine.push("Integrated dual-diagnosis treatment for comorbid SUD");
    urgent.push("Comorbid substance use disorder — integrated treatment required");
  }

  return {
    condition: "bpd",
    primaryRecommendation: {
      indication: `Borderline Personality Disorder${input.currentCrisis ? " — Acute Crisis" : ""}`,
      firstLineIntervention: firstLine,
      pharmacotherapy,
      psychotherapy: "DBT (first-line), MBT, TFP, or Schema Therapy — all evidence-based. Minimum 1 year of structured psychotherapy recommended.",
      levelOfCare: input.currentCrisis ? "Crisis stabilization / brief inpatient if safety concern" : input.priorDBT && input.priorMBT ? "Intensive outpatient or partial hospitalization" : "Outpatient structured psychotherapy",
      cor: "Strong",
      loe: "A",
      guidelineSource: "APA Practice Guideline for Borderline Personality Disorder 2025",
      notes,
    },
    alternativeRecommendations: [
      {
        indication: "Acute crisis / self-harm episode",
        intervention: "Brief crisis stabilization (not prolonged hospitalization — may reinforce maladaptive patterns). Crisis safety plan. DBT crisis coaching.",
        notes: "APA 2025: Avoid prolonged hospitalization for BPD crises unless immediate safety risk. Brief stabilization preferred.",
      },
      {
        indication: "Comorbid bipolar disorder",
        intervention: "Mood stabilizer (lithium, lamotrigine, or valproate) for bipolar component. Psychotherapy continues.",
        notes: "Distinguish BPD mood instability from bipolar disorder — different treatment targets.",
      },
    ],
    urgentFlags: urgent,
    safetyConsiderations: [
      ...safety,
      "Suicide risk is elevated in BPD — assess at every visit",
      "Non-suicidal self-injury (NSSI) requires safety planning, not automatic hospitalization",
      "Avoid benzodiazepines (high misuse potential in BPD)",
      "Therapeutic alliance is critical — rupture repair is part of treatment",
    ],
    monitoringParameters: ["PHQ-9 for comorbid depression", "Columbia Suicide Severity Rating Scale (C-SSRS)", "Medication side effects if pharmacotherapy used", "Functional outcomes and quality of life"],
    multidisciplinaryConsult: ["Psychotherapy specialist (DBT-trained therapist)", "Social work (housing, safety planning)", "Substance use treatment if SUD comorbid"],
    references: [
      { citation: "American Psychiatric Association. Practice Guideline for Borderline Personality Disorder. 2025", year: 2025 },
      { citation: "Linehan MM et al. Arch Gen Psychiatry 1991 (Original DBT RCT)", year: 1991 },
      { citation: "Bateman A, Fonagy P. Am J Psychiatry 1999 (MBT RCT)", year: 1999 },
      { citation: "Cristea IA et al. JAMA Psychiatry 2017 (Meta-analysis of psychotherapies for BPD)", year: 2017 },
    ],
    guidelineYear: "2025",
    practiceChangingNote,
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// DEPRESSION — APA 2025-2026 UPDATE + TRD
// ─────────────────────────────────────────────────────────────────────────────

function evaluateDepression(input: DepressionInput): PsychRecommendation {
  const urgent: string[] = [];
  const safety: string[] = [];

  if (input.suicidalIdeation) {
    urgent.push("Active suicidal ideation — safety assessment required; consider hospitalization");
  }
  if (input.bipolarHistory) {
    urgent.push("Bipolar history — antidepressant monotherapy may precipitate mania; mood stabilizer required");
    safety.push("Do NOT use antidepressant monotherapy in bipolar depression without mood stabilizer");
  }
  if (input.psychoticFeatures) {
    urgent.push("Psychotic depression — antidepressant + antipsychotic combination required; consider ECT");
  }

  let firstLine: string[] = [];
  let pharmacotherapy = "";
  let notes = "";
  let practiceChangingNote = "";

  if (input.trd || input.trialsFailed >= 2) {
    // Treatment-Resistant Depression
    firstLine = [
      "Esketamine (SPRAVATO) intranasal — FDA-approved for TRD (2019) and MDD with acute SI (2020)",
      "Electroconvulsive Therapy (ECT) — most effective for severe/TRD/psychotic depression",
      "Augmentation: lithium + antidepressant (evidence-based)",
      "Augmentation: atypical antipsychotic (aripiprazole, quetiapine, brexpiprazole)",
      "Transcranial Magnetic Stimulation (TMS) — FDA-cleared for TRD",
      "MAOIs (phenelzine, tranylcypromine) — highly effective, require dietary restrictions",
    ];
    pharmacotherapy = `TRD (${input.trialsFailed} failed adequate trials): Esketamine (SPRAVATO) if eligible, or ECT for severe cases. Augmentation with lithium, atypical antipsychotic, or thyroid hormone. Consider MAOI if other strategies fail.`;
    notes = "APA 2025-2026 UPDATE: TRD pathway now includes esketamine as a first-line option after ≥2 failed trials. ECT remains the gold standard for severe TRD. Measurement-based care (PHQ-9 at every visit) is recommended.";
    practiceChangingNote = "APA 2025-2026 UPDATE: Esketamine (SPRAVATO) is now incorporated into the TRD pathway. Measurement-based care is a core recommendation.";
  } else if (input.severity === "severe" || input.psychoticFeatures) {
    firstLine = [
      "SSRI or SNRI (first-line pharmacotherapy)",
      "Psychotherapy (CBT or IPT) — combination with pharmacotherapy preferred for severe MDD",
      "ECT if psychotic features, catatonia, or severe suicidality",
    ];
    pharmacotherapy = input.psychoticFeatures
      ? "Antidepressant + antipsychotic combination (e.g., sertraline + olanzapine). ECT preferred for psychotic depression."
      : "SSRI (sertraline, escitalopram) or SNRI (venlafaxine, duloxetine). Combination with psychotherapy.";
    notes = "Severe MDD: combination of pharmacotherapy + psychotherapy is more effective than either alone. ECT for psychotic features.";
  } else if (input.pregnancyOrPostpartum) {
    firstLine = [
      "Psychotherapy (CBT, IPT) — preferred first-line for mild-moderate PPD",
      "SSRI (sertraline preferred — lowest breast milk transfer) for moderate-severe PPD",
      "Brexanolone (Zulresso) IV — FDA-approved for postpartum depression",
      "Zuranolone (Zurzuvae) oral — FDA-approved 2023 for PPD",
    ];
    pharmacotherapy = "Sertraline (preferred SSRI in pregnancy/lactation). Brexanolone or zuranolone for PPD. Avoid paroxetine in pregnancy (cardiac defects). Avoid benzodiazepines.";
    notes = "Postpartum depression: brexanolone and zuranolone are FDA-approved specifically for PPD. Shared decision-making regarding breastfeeding and medication.";
  } else {
    // Mild-moderate MDD
    firstLine = [
      "SSRI (escitalopram, sertraline) — first-line",
      "SNRI (venlafaxine, duloxetine) — first-line alternative",
      "Psychotherapy (CBT, IPT, behavioral activation) — equivalent to medication for mild-moderate MDD",
      "Combination therapy for moderate-severe MDD",
    ];
    pharmacotherapy = "SSRI (escitalopram 10–20 mg or sertraline 50–200 mg) or SNRI. Adequate trial = 4–8 weeks at therapeutic dose. Reassess at 4 weeks.";
    notes = "Mild-moderate MDD: psychotherapy alone is equivalent to medication. Combination preferred for moderate-severe. Measurement-based care (PHQ-9 at every visit) recommended by APA 2025-2026.";
  }

  if (input.measurementBasedCare) {
    notes += " Measurement-based care (PHQ-9 at every visit) is being used — this is a core APA 2025-2026 recommendation.";
  }

  return {
    condition: "depression",
    primaryRecommendation: {
      indication: `Major Depressive Disorder — ${input.severity || "unspecified severity"}${input.trd ? " (Treatment-Resistant)" : ""}${input.pregnancyOrPostpartum ? " (Perinatal)" : ""}`,
      firstLineIntervention: firstLine,
      pharmacotherapy,
      psychotherapy: input.trd ? "CBT, IPT, or behavioral activation as adjunct to pharmacotherapy/ECT/TMS" : "CBT or IPT — equivalent to medication for mild-moderate MDD; combination preferred for severe MDD",
      levelOfCare: input.suicidalIdeation ? "Inpatient or crisis stabilization" : input.trd || input.severity === "severe" ? "Outpatient with close follow-up (2–4 weeks) or partial hospitalization" : "Outpatient",
      cor: "Strong",
      loe: "A",
      guidelineSource: "APA Practice Guideline for Major Depressive Disorder 2025-2026 Update",
      notes,
    },
    alternativeRecommendations: [
      {
        indication: "Inadequate response after 4–8 weeks",
        intervention: "Optimize dose → switch within class → augment (lithium, atypical antipsychotic, buspirone) → switch class → TRD pathway",
        notes: "Sequential treatment algorithm. Reassess diagnosis before declaring TRD.",
      },
      {
        indication: "Seasonal affective disorder (SAD)",
        intervention: "Light therapy (10,000 lux, 30 min morning) ± bupropion XL (FDA-approved for SAD prevention)",
        notes: "Light therapy is first-line for SAD. Bupropion XL started in fall for prevention.",
      },
      {
        indication: "Anxious depression",
        intervention: "SSRI/SNRI + buspirone or low-dose benzodiazepine (short-term). Avoid benzodiazepine long-term.",
        notes: "Anxious depression may respond better to SNRI than SSRI.",
      },
    ],
    urgentFlags: urgent,
    safetyConsiderations: [
      ...safety,
      "Black box warning: increased suicidality in children/adolescents/young adults on antidepressants — monitor closely",
      "SSRI discontinuation syndrome — taper gradually",
      "Serotonin syndrome risk with combination serotonergic agents",
      "QTc prolongation with citalopram >40 mg/day",
      "Esketamine (SPRAVATO): REMS program required; monitor for dissociation and BP for 2 hours post-dose",
    ],
    monitoringParameters: ["PHQ-9 at every visit (measurement-based care)", "Columbia C-SSRS for suicidality", "Side effect assessment at 2 and 4 weeks", "Metabolic monitoring if atypical antipsychotic augmentation"],
    multidisciplinaryConsult: ["Psychotherapy (CBT/IPT therapist)", "ECT service if severe/TRD/psychotic", "Reproductive psychiatry if perinatal"],
    references: [
      { citation: "American Psychiatric Association. Practice Guideline for Major Depressive Disorder. 2025-2026 Update", year: 2025 },
      { citation: "Papakostas GI et al. NEJM 2020 (Esketamine for TRD — TRANSFORM trials)", year: 2020 },
      { citation: "UK ECT Review Group. Lancet 2003 (ECT meta-analysis)", year: 2003 },
      { citation: "Brexanolone FDA approval 2019 (Zulresso for PPD)", year: 2019 },
      { citation: "Zuranolone FDA approval 2023 (Zurzuvae for MDD and PPD)", year: 2023 },
    ],
    guidelineYear: "2025-2026",
    practiceChangingNote,
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// SCHIZOPHRENIA — APA 2020 (STILL DOMINANT)
// ─────────────────────────────────────────────────────────────────────────────

function evaluateSchizophrenia(input: SchizophreniaInput): PsychRecommendation {
  const urgent: string[] = [];
  const safety: string[] = [];

  if (input.acuteExacerbation) {
    urgent.push("Acute psychotic exacerbation — assess safety, consider inpatient stabilization");
  }
  if (input.treatmentResistant && !input.clozapineEligible) {
    urgent.push("Treatment-resistant schizophrenia — clozapine evaluation required (failed ≥2 adequate antipsychotic trials)");
  }
  if (input.tardiveDyskinesia) {
    safety.push("Tardive dyskinesia present — consider VMAT2 inhibitor (valbenazine or deutetrabenazine); review antipsychotic necessity");
  }

  let firstLine: string[] = [];
  let pharmacotherapy = "";
  let notes = "";

  if (input.treatmentResistant && input.clozapineEligible) {
    firstLine = ["Clozapine — only antipsychotic with evidence for treatment-resistant schizophrenia", "Psychosocial rehabilitation", "Assertive Community Treatment (ACT) if available"];
    pharmacotherapy = "Clozapine (titrate to 300–450 mg/day; target trough 350–600 ng/mL). Requires REMS enrollment (ANC monitoring). Most effective antipsychotic for TRS.";
    notes = "APA 2020: Clozapine is the only evidence-based treatment for treatment-resistant schizophrenia. Underutilized in practice. REMS monitoring required (ANC weekly × 6 months, then biweekly × 6 months, then monthly).";
  } else if (input.firstEpisode) {
    firstLine = ["Second-generation antipsychotic (SGA) — first-line for first-episode psychosis", "Coordinated Specialty Care (CSC) program", "Family psychoeducation", "Cognitive Behavioral Therapy for Psychosis (CBTp)"];
    pharmacotherapy = "SGA: aripiprazole, risperidone, olanzapine, or quetiapine. Start low, titrate slowly. First-episode patients often respond to lower doses.";
    notes = "First-episode psychosis: Coordinated Specialty Care (CSC) programs (e.g., NAVIGATE, OnTrackNY) significantly improve outcomes. Early intervention is critical.";
  } else if (input.nonadherence || input.laiCandidate) {
    firstLine = ["Long-Acting Injectable (LAI) antipsychotic — strongly preferred for nonadherence", "Motivational interviewing for medication adherence", "Assertive Community Treatment (ACT)"];
    pharmacotherapy = `LAI options: aripiprazole lauroxil (Aristada), paliperidone palmitate (Invega Sustenna/Trinza), risperidone LAI (Risperdal Consta), haloperidol decanoate. ${input.currentAntipsychotic ? `Current oral: ${input.currentAntipsychotic} — consider LAI equivalent.` : ""}`;
    notes = "LAI antipsychotics reduce relapse rates by 30–50% vs oral in nonadherent patients. APA 2020 strongly recommends LAI discussion with all patients.";
  } else {
    firstLine = ["Second-generation antipsychotic (SGA) — continue/optimize", "Psychosocial interventions (CBTp, social skills training, supported employment)", "Family psychoeducation"];
    pharmacotherapy = `${input.currentAntipsychotic ? `Continue ${input.currentAntipsychotic} at therapeutic dose. ` : "SGA: aripiprazole, risperidone, olanzapine, quetiapine, or lurasidone. "}Assess response at 4–6 weeks. Consider LAI if adherence concern.`;
    notes = "Maintenance antipsychotic therapy is essential for relapse prevention. Psychosocial interventions are additive to pharmacotherapy.";
  }

  if (input.metabolicConcerns) {
    safety.push("Metabolic monitoring required: weight, BMI, fasting glucose, lipids, BP at baseline and every 3 months");
    firstLine.push("Consider metabolically neutral antipsychotic (aripiprazole, lurasidone, ziprasidone) if metabolic concerns");
  }

  return {
    condition: "schizophrenia",
    primaryRecommendation: {
      indication: `Schizophrenia${input.firstEpisode ? " — First Episode" : ""}${input.treatmentResistant ? " — Treatment-Resistant" : ""}${input.acuteExacerbation ? " — Acute Exacerbation" : ""}`,
      firstLineIntervention: firstLine,
      pharmacotherapy,
      psychotherapy: "Cognitive Behavioral Therapy for Psychosis (CBTp), social skills training, supported employment (IPS), family psychoeducation — all evidence-based adjuncts",
      levelOfCare: input.acuteExacerbation ? "Inpatient stabilization" : input.treatmentResistant ? "Intensive outpatient or ACT" : "Outpatient with regular follow-up",
      cor: "Strong",
      loe: "A",
      guidelineSource: "APA Practice Guideline for Schizophrenia 2020 (current standard 2026)",
      notes,
    },
    alternativeRecommendations: [
      {
        indication: "Clozapine-refractory schizophrenia",
        intervention: "Clozapine + amisulpride augmentation (CATIE-like strategy). ECT augmentation for refractory cases.",
        notes: "Limited evidence for clozapine augmentation. Specialist consultation recommended.",
      },
      {
        indication: "Tardive dyskinesia",
        intervention: "Valbenazine (Ingrezza) or deutetrabenazine (Austedo) — FDA-approved VMAT2 inhibitors for TD",
        notes: "Do not abruptly discontinue antipsychotic (may worsen TD). VMAT2 inhibitors are first-line for TD.",
