function evaluateEatingDisorder(input: EatingDisorderInput): PsychRecommendation {
  const urgent: string[] = [];
  const safety: string[] = [];

  if (input.medicallyUnstable) {
    urgent.push("Medically unstable — inpatient medical stabilization required before psychiatric treatment");
  }
  if (input.edType === "AN" && input.bmi < 15) {
    urgent.push("Severe anorexia nervosa (BMI <15) — high mortality risk; consider inpatient or residential treatment");
  }
  if (input.edType === "AN" && input.bmi < 17.5) {
    safety.push("Refeeding syndrome risk — medical monitoring required during nutritional rehabilitation");
  }

  let firstLine: string[] = [];
  let pharmacotherapy = "";
  let notes = "";

  if (input.edType === "AN") {
    if (input.pediatric || input.age < 18) {
      firstLine = ["Family-Based Treatment (FBT/Maudsley) — first-line for adolescent AN (strongest evidence)", "Nutritional rehabilitation (supervised refeeding)", "Medical monitoring (vitals, ECG, labs)"];
      pharmacotherapy = "No medication is FDA-approved for AN. Olanzapine may be used adjunctively for weight gain and anxiety (limited evidence). Avoid SSRIs in underweight AN (ineffective).";
      notes = "APA 2023: FBT (Maudsley approach) is the most evidence-based treatment for adolescent AN. Nutritional rehabilitation is the primary intervention.";
    } else {
      firstLine = ["Cognitive Behavioral Therapy for Eating Disorders (CBT-E)", "Specialist Supportive Clinical Management (SSCM)", "Nutritional rehabilitation with dietitian", "Higher level of care (IOP, residential, inpatient) based on BMI and medical stability"];
      pharmacotherapy = "No FDA-approved medication for AN. Olanzapine (2.5–10 mg) may support weight restoration in adults. Avoid SSRIs in underweight patients.";
      notes = "Adult AN: CBT-E and SSCM have the best evidence. Higher level of care is often required. Medical monitoring essential during refeeding.";
    }
  } else if (input.edType === "BN") {
    firstLine = ["Cognitive Behavioral Therapy for Bulimia (CBT-BN) — first-line (strongest evidence)", "Interpersonal Therapy (IPT) — alternative", "Nutritional counseling"];
    pharmacotherapy = "Fluoxetine 60 mg/day — only FDA-approved medication for BN (Category 1). Higher dose than for MDD. Avoid bupropion (seizure risk in BN).";
    notes = "APA 2023: CBT-BN is the most effective treatment for bulimia. Fluoxetine 60 mg is FDA-approved and additive to CBT. Avoid bupropion (lowers seizure threshold in purging behavior).";
